// Sleep insight index — record JAH-GAI-SLEEPHEADBAND-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"eeg_channels": 4, "battery_nights": 3, "price_usd": 400};
var value = (m.eeg_channels*m.battery_nights/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAI-SLEEPHEADBAND-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAI-SLEEPHEADBAND-000001|' + value.toFixed(2) + ' insight index');

